type AssessmentStatus = "complete" | "late" | "missing" | "absent" | "incomplete" | "not-entered";
type PortalQuestion = { label: string; score: number | null; max: number; pct: number | null; classBenchmark: { average: number; pct: number; peerCount: number } | null; topic: { level: string; learningUnit: string; objective: string } | null };
type PortalClassBenchmark = { averagePct: number; peerCount: number; rank: number | null; rankedCount: number };
type PortalAssessment = { id: string; yearLabel: string; subjectId: string; subjectCode: string; subjectName: string; className: string; code: string; title: string; date: string; term: string; nature: string; isExam: boolean; status: AssessmentStatus; total: number | null; max: number; pct: number | null; classBenchmark: PortalClassBenchmark | null; questions: PortalQuestion[] };
type PortalTopic = { id: string; learningUnit: string; objective: string; level: string; earned: number; max: number; pct: number; itemCount: number; assessmentCount: number };
type PortalReport = { student: { studentNumber: string; name: string; observedNames: string[]; recordCount: number }; summary: { assessmentCount: number; scoredCount: number; averagePct: number | null; absentCount: number; lateCount: number; missingCount: number }; subjects: Array<{ subjectId: string; subjectCode: string; subjectName: string; records: PortalAssessment[] }>; assessments: PortalAssessment[]; topics: PortalTopic[] };
type TopicStatus = "strong" | "developing" | "priority";
type StudentRevisionStatus = "completed" | "review";
type StudentLanguage = "zh" | "en";
type TopicUnit = { id: string; subjectId: string; label: string; learningUnit: string; level: string; earned: number; max: number; pct: number; itemCount: number; assessmentCount: number; objectives: PortalTopic[]; status: TopicStatus };

const escapeHtml = (value: string | number | null | undefined) => String(value ?? "").replace(/[&<>'"]/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[character] ?? character));
const scoreTone = (pct: number | null | undefined) => pct === null || pct === undefined ? "text-slate-400" : pct >= 70 ? "text-emerald-600" : pct >= 50 ? "text-amber-600" : "text-red-600";
const scoreBackground = (pct: number) => pct >= 70 ? "bg-emerald-500" : pct >= 50 ? "bg-amber-500" : "bg-red-500";
const colorForPct = (pct: number) => pct >= 70 ? "#10b981" : pct >= 50 ? "#f59e0b" : "#ef4444";

function statusLabel(status: AssessmentStatus, language: StudentLanguage = "zh") {
  const labels = language === "en"
    ? { complete: "Completed", late: "Late (raw × 70%)", missing: "Missing (0)", absent: "Absent (0)", incomplete: "Partially entered", "not-entered": "Not entered" }
    : { complete: "已完成", late: "遲交（原分 × 70%）", missing: "欠交（0 分）", absent: "缺席（0 分）", incomplete: "未完成輸入", "not-entered": "尚未輸入" };
  return labels[status];
}
function statusStyle(status: AssessmentStatus) {
  if (status === "complete") return "bg-emerald-50 text-emerald-700 border-emerald-200";
  if (status === "late") return "bg-violet-50 text-violet-700 border-violet-200";
  if (status === "missing") return "bg-rose-50 text-rose-700 border-rose-200";
  if (status === "absent") return "bg-orange-50 text-orange-700 border-orange-200";
  return "bg-slate-100 text-slate-600 border-slate-200";
}
function topicStatus(pct: number): TopicStatus { return pct >= 70 ? "strong" : pct >= 50 ? "developing" : "priority"; }
function topicStatusLabel(status: TopicStatus, language: StudentLanguage = "zh") {
  if (language === "en") return status === "strong" ? "Strength" : status === "developing" ? "Developing" : "Priority";
  return status === "strong" ? "強項" : status === "developing" ? "需鞏固" : "優先跟進";
}
function topicStatusClass(status: TopicStatus) { return status === "strong" ? "bg-emerald-100 text-emerald-700" : status === "developing" ? "bg-amber-100 text-amber-700" : "bg-red-100 text-red-700"; }

function buildTopicUnits(topics: PortalTopic[], subjects: PortalReport["subjects"], subjectId: string): TopicUnit[] {
  const subjectMap = new Map(subjects.map(subject => [subject.subjectId, subject]));
  const groups = new Map<string, Omit<TopicUnit, "pct" | "status">>();
  topics.filter(topic => subjectId === "all" || topic.id.startsWith(`${subjectId}::`)).forEach(topic => {
    const actualSubjectId = topic.id.split("::")[0] || "";
    const key = `${actualSubjectId}::${topic.learningUnit}`;
    const subject = subjectMap.get(actualSubjectId);
    const current = groups.get(key) ?? { id: key, subjectId: actualSubjectId, label: subject ? `${subject.subjectCode} · ${topic.learningUnit}` : topic.learningUnit, learningUnit: topic.learningUnit, level: topic.level, earned: 0, max: 0, itemCount: 0, assessmentCount: 0, objectives: [] };
    current.earned += topic.earned;
    current.max += topic.max;
    current.itemCount += topic.itemCount;
    current.assessmentCount = Math.max(current.assessmentCount, topic.assessmentCount);
    current.objectives.push(topic);
    groups.set(key, current);
  });
  return Array.from(groups.values()).map(unit => ({ ...unit, pct: unit.max > 0 ? Math.round((unit.earned / unit.max) * 100) : 0, status: topicStatus(unit.max > 0 ? Math.round((unit.earned / unit.max) * 100) : 0) })).sort((a, b) => a.pct - b.pct || b.max - a.max);
}

function subjectYearSummary(assessments: PortalAssessment[]) {
  return Array.from(assessments.filter(assessment => assessment.pct !== null).reduce((groups, assessment) => {
    const key = `${assessment.yearLabel}::${assessment.subjectId}`;
    const current = groups.get(key) ?? { key, yearLabel: assessment.yearLabel, subjectCode: assessment.subjectCode, subjectName: assessment.subjectName, total: 0, count: 0 };
    current.total += assessment.pct ?? 0;
    current.count += 1;
    groups.set(key, current);
    return groups;
  }, new Map<string, { key: string; yearLabel: string; subjectCode: string; subjectName: string; total: number; count: number }>()).values()).map(item => ({ ...item, pct: Math.round(item.total / item.count), shortLabel: `${item.yearLabel.replace(/^20/, "")}/${item.subjectCode}` }));
}

function yearSummary(assessments: PortalAssessment[]) {
  return Array.from(assessments.filter(assessment => assessment.pct !== null).reduce((groups, assessment) => {
    const current = groups.get(assessment.yearLabel) ?? { yearLabel: assessment.yearLabel, total: 0, count: 0, subjects: new Set<string>() };
    current.total += assessment.pct ?? 0;
    current.count += 1;
    current.subjects.add(assessment.subjectCode);
    groups.set(assessment.yearLabel, current);
    return groups;
  }, new Map<string, { yearLabel: string; total: number; count: number; subjects: Set<string> }>()).values()).map(item => ({ ...item, pct: Math.round(item.total / item.count), subjects: Array.from(item.subjects).join(" · ") }));
}

function classComparisonSummary(assessments: PortalAssessment[]) {
  const eligible = assessments.filter(assessment => assessment.pct !== null && assessment.classBenchmark !== null);
  if (!eligible.length) return null;
  const personalAverage = Math.round(eligible.reduce((sum, assessment) => sum + (assessment.pct ?? 0), 0) / eligible.length);
  const classAverage = Math.round(eligible.reduce((sum, assessment) => sum + (assessment.classBenchmark?.averagePct ?? 0), 0) / eligible.length);
  return {
    personalAverage,
    classAverage,
    gap: personalAverage - classAverage,
    assessmentCount: eligible.length,
    minimumPeerCount: Math.min(...eligible.map(assessment => assessment.classBenchmark?.peerCount ?? 0)),
    rows: eligible.map(assessment => ({
      label: `${assessment.yearLabel} · ${assessment.code || assessment.title}`,
      fullLabel: `${assessment.yearLabel} · ${assessment.className} · ${assessment.subjectCode} · ${assessment.title}`,
      personalPct: assessment.pct ?? 0,
      classAverage: assessment.classBenchmark?.averagePct ?? 0,
      gap: (assessment.pct ?? 0) - (assessment.classBenchmark?.averagePct ?? 0),
    })),
  };
}

function getRecommendations(priority: TopicUnit[], developing: TopicUnit[], strengths: TopicUnit[], language: StudentLanguage = "zh") {
  const english = language === "en";
  return [
    ...priority.slice(0, 2).map(topic => ({ tone: "priority" as const, title: english ? `Priority review: ${topic.learningUnit}` : `優先鞏固：${topic.learningUnit}`, body: english ? "Review the core concept and worked examples first, then complete foundation practice and use short questions to check understanding." : "先重溫核心概念與例題，逐步完成基礎練習；完成後以短題目檢查理解。", topic })),
    ...developing.slice(0, priority.length ? 1 : 2).map(topic => ({ tone: "developing" as const, title: english ? `Build consistency: ${topic.learningUnit}` : `鞏固提升：${topic.learningUnit}`, body: english ? "The foundation is there but performance is not yet consistent. Redo incorrect questions, explain each step, and practise mixed question types." : "已有基礎但表現未穩定。建議重做錯題、說明每一步的理由，並加入混合題型練習。", topic })),
    ...strengths.slice(0, 1).map(topic => ({ tone: "strong" as const, title: english ? `Extend a strength: ${topic.learningUnit}` : `延伸強項：${topic.learningUnit}`, body: english ? "Try multi-step, non-routine, or application questions, while retaining a small amount of review practice to keep this skill secure." : "可挑戰多步、非例行或應用題，同時保留少量複習題，以維持熟練度。", topic })),
  ];
}

function topicRadarSvg(units: TopicUnit[]) {
  const radar = [...units].sort((a, b) => b.max - a.max).slice(0, 6);
  if (radar.length < 3) return "";
  const width = 560, height = 250, cx = 178, cy = 125, radius = 76;
  const point = (distance: number, index: number) => { const angle = -Math.PI / 2 + (Math.PI * 2 * index) / radar.length; return { x: cx + Math.cos(angle) * distance, y: cy + Math.sin(angle) * distance }; };
  const polygon = (distance: number) => radar.map((_unit, index) => { const p = point(distance, index); return `${p.x.toFixed(1)},${p.y.toFixed(1)}`; }).join(" ");
  const valuePolygon = radar.map((unit, index) => { const p = point(radius * unit.pct / 100, index); return `${p.x.toFixed(1)},${p.y.toFixed(1)}`; }).join(" ");
  const legend = radar.map((unit, index) => `<div class="legend"><i>${index + 1}</i><span><b>${escapeHtml(unit.label)}</b><small>${unit.earned}/${unit.max} · ${unit.pct}% · ${unit.assessmentCount} 項評估</small></span></div>`).join("");
  return `<div class="radar-wrap"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="課題雷達圖">${[25, 50, 75, 100].map(value => `<polygon points="${polygon(radius * value / 100)}" fill="none" stroke="#dbeafe" stroke-width="1"/>`).join("")}${radar.map((unit, index) => { const end = point(radius, index); const label = point(radius + 22, index); const anchor = label.x < cx - 10 ? "end" : label.x > cx + 10 ? "start" : "middle"; return `<line x1="${cx}" y1="${cy}" x2="${end.x}" y2="${end.y}" stroke="#bfdbfe"/><text x="${label.x}" y="${label.y + 3}" text-anchor="${anchor}" fill="#475569" font-size="8">${index + 1}. ${escapeHtml(unit.learningUnit.slice(0, 22))}</text>`; }).join("")}<polygon points="${valuePolygon}" fill="#0f766e" fill-opacity=".18" stroke="#0f766e" stroke-width="2"/>${radar.map((unit, index) => { const p = point(radius * unit.pct / 100, index); return `<circle cx="${p.x}" cy="${p.y}" r="3" fill="${colorForPct(unit.pct)}"/>`; }).join("")}</svg><div class="radar-legend">${legend}</div></div>`;
}

function printStudentReport(report: PortalReport, selectedSubjectId: string) {
  const subject = selectedSubjectId === "all" ? null : report.subjects.find(item => item.subjectId === selectedSubjectId);
  const scope = subject ? `${subject.subjectCode} · ${subject.subjectName}` : "所有科目";
  const assessments = report.assessments.filter(item => selectedSubjectId === "all" || item.subjectId === selectedSubjectId);
  const scored = assessments.filter(item => item.pct !== null);
  const topics = report.topics.filter(topic => selectedSubjectId === "all" || topic.id.startsWith(`${selectedSubjectId}::`));
  const units = buildTopicUnits(topics, report.subjects, selectedSubjectId);
  const strengths = units.filter(unit => unit.status === "strong").sort((a, b) => b.pct - a.pct).slice(0, 3);
  const priority = units.filter(unit => unit.status === "priority").slice(0, 3);
  const developing = units.filter(unit => unit.status === "developing").slice(0, 2);
  const recommendations = getRecommendations(priority, developing, strengths);
  const years = yearSummary(assessments);
  const average = scored.length ? Math.round(scored.reduce((sum, item) => sum + (item.pct ?? 0), 0) / scored.length) : null;
  const trend = scored.length >= 2 ? (scored[scored.length - 1].pct ?? 0) - (scored[0].pct ?? 0) : null;
  const radar = topicRadarSvg(units);
  const topicRows = units.map(unit => `<tr><td><b>${escapeHtml(unit.label)}</b><small>${escapeHtml(unit.level)} · ${unit.objectives.map(topic => escapeHtml(topic.objective)).join("；")}</small></td><td class="center">${unit.earned}/${unit.max}</td><td class="center ${unit.status}">${unit.pct}%</td><td class="center"><em class="tag ${unit.status}">${topicStatusLabel(unit.status)}</em></td></tr>`).join("") || `<tr><td colspan="4" class="muted">尚未有已完成並已標記課題的個人成績。</td></tr>`;
  const yearsRows = years.map(year => `<tr><td><b>${escapeHtml(year.yearLabel)}</b><small>${escapeHtml(year.subjects)} · ${year.count} 項評估</small></td><td class="right ${year.pct >= 70 ? "good" : year.pct >= 50 ? "mid" : "low"}">${year.pct}%</td></tr>`).join("") || `<tr><td class="muted">尚未有可分析學年資料。</td></tr>`;
  const recommendationRows = recommendations.map(item => `<div class="recommendation ${item.tone}"><b>${escapeHtml(item.title)}</b><p>${escapeHtml(item.body)}</p><small>${escapeHtml(item.topic.label)} · ${item.topic.earned}/${item.topic.max} · ${item.topic.pct}%</small></div>`).join("");
  const assessmentRows = assessments.map(assessment => {
    const answered = assessment.questions.filter(question => question.pct !== null);
    const low = [...answered].sort((a, b) => (a.pct ?? 101) - (b.pct ?? 101)).slice(0, 3);
    const high = [...answered].sort((a, b) => (b.pct ?? -1) - (a.pct ?? -1)).slice(0, 2);
    const diagnosis = assessment.status === "complete" || assessment.status === "late" ? `<div class="diagnosis"><div><b>個人判讀</b><p>已完成 ${answered.length}/${assessment.questions.length} 題；本次表現 ${assessment.pct ?? "—"}%${low[0]?.topic ? `，優先重溫「${escapeHtml(low[0].topic.learningUnit)}」` : ""}。</p></div><div><b>優先跟進</b><p>${low.map(question => `${escapeHtml(question.label)} ${question.pct}%${question.topic ? ` · ${escapeHtml(question.topic.learningUnit)}` : ""}`).join("；") || "暫無可判讀題目。"}</p></div><div><b>可延伸</b><p>${high.map(question => `${escapeHtml(question.label)} ${question.pct}%`).join("；") || "暫無可判讀題目。"}</p></div></div>` : `<p class="notice">${escapeHtml(statusLabel(assessment.status))}：此項不納入課題強弱分析；個人成績已按相應規則顯示。</p>`;
    const questionRows = assessment.questions.map(question => `<tr><td>${escapeHtml(question.label)} / ${question.max}</td><td>${question.topic ? `<b>${escapeHtml(question.topic.level)} · ${escapeHtml(question.topic.learningUnit)}</b><small>${escapeHtml(question.topic.objective)}</small>` : `<span class="muted">未標記課題</span>`}</td><td class="center">${question.score === null ? "—" : `${question.score}/${question.max}`}</td><td class="center ${question.pct !== null && question.pct >= 70 ? "good" : question.pct !== null && question.pct >= 50 ? "mid" : "low"}">${question.pct === null ? "—" : `${question.pct}%`}</td></tr>`).join("") || `<tr><td colspan="4" class="muted">未有評分表資料。</td></tr>`;
    return `<section class="assessment"><header><div><h3>${escapeHtml(assessment.title)}${assessment.code ? ` <span>(${escapeHtml(assessment.code)})</span>` : ""}</h3><p>${escapeHtml(assessment.yearLabel)} · ${escapeHtml(assessment.subjectCode)} · ${escapeHtml(assessment.className)} · ${escapeHtml(assessment.nature)}${assessment.date ? ` · ${escapeHtml(assessment.date)}` : ""}</p></div><div class="result"><b>${assessment.total === null ? "—" : `${assessment.total}/${assessment.max}`}</b><span>${assessment.pct === null ? "未計分" : `${assessment.pct}%`}</span><em class="tag ${assessment.status}">${escapeHtml(statusLabel(assessment.status))}</em></div></header>${diagnosis}<table><thead><tr><th>題號</th><th>所屬課題／學習目標</th><th>個人得分</th><th>%</th></tr></thead><tbody>${questionRows}</tbody></table></section>`;
  }).join("") || `<p class="muted">此範圍暫無評估紀錄。</p>`;
  const html = `<!doctype html><html lang="zh-Hant"><head><meta charset="UTF-8"><title>${escapeHtml(report.student.studentNumber)} ${escapeHtml(scope)} 成績報告</title><style>@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#fff;color:#172033;font-family:Arial,'Microsoft JhengHei','PingFang TC',sans-serif;font-size:11px;line-height:1.45}.page{width:210mm;min-height:297mm;padding:14mm 13mm 16mm}.hero{display:flex;justify-content:space-between;gap:16px;border-bottom:3px solid #0f766e;padding-bottom:10px}.hero h1{margin:0;color:#0f766e;font-size:21px}.hero p{margin:4px 0;color:#64748b}.scope{text-align:right;font-weight:700;color:#0f766e}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:12px 0}.stat{border:1px solid #dbe4ea;border-radius:7px;padding:8px;background:#fbfdff}.stat span{display:block;font-size:9px;color:#64748b}.stat b{display:block;margin-top:2px;font-size:18px;color:#0f172a}.section{margin-top:14px;break-inside:avoid}.title{margin:0 0 7px;border-left:4px solid #0f766e;padding-left:7px;font-size:14px}.insights{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.insight{border:1px solid #dbeafe;border-radius:5px;padding:6px;background:#f8fbff}.insight b{font-size:9px;color:#0f766e}.insight p{margin:3px 0 0;font-size:9px;color:#475569}.radar-wrap{display:grid;grid-template-columns:1.15fr .85fr;gap:8px;align-items:center;border:1px solid #dbeafe;border-radius:7px;padding:7px;background:#fbfdff}.radar-wrap svg{display:block;width:100%;height:190px}.radar-legend{display:grid;gap:4px}.legend{display:flex;gap:5px;font-size:8px}.legend i{display:inline-flex;align-items:center;justify-content:center;flex:0 0 13px;height:13px;border-radius:50%;background:#0f766e;color:#fff;font-style:normal}.legend b,.legend small,td small{display:block}.legend small,small,.muted{color:#64748b}table{width:100%;border-collapse:collapse;font-size:9px}th{padding:5px 6px;background:#0f766e;color:#fff;text-align:left}td{padding:5px 6px;border-bottom:1px solid #e2e8f0;vertical-align:top}.center{text-align:center;font-family:ui-monospace,SFMono-Regular,monospace}.right{text-align:right;font-family:ui-monospace,SFMono-Regular,monospace}.good,.strong{color:#15803d}.mid,.developing{color:#b45309}.low,.priority{color:#b91c1c}.tag{display:inline-block;padding:1px 4px;border-radius:4px;font-size:8px;font-style:normal}.tag.strong,.tag.complete{background:#dcfce7}.tag.developing,.tag.late{background:#fef3c7}.tag.priority,.tag.missing{background:#fee2e2}.tag.absent{background:#ffedd5}.recommendations{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:7px}.recommendation{border:1px solid #e2e8f0;border-radius:5px;padding:6px;background:#fff;font-size:8px}.recommendation p{margin:3px 0;color:#475569}.recommendation.priority{border-color:#fecaca;background:#fef2f2}.recommendation.developing{border-color:#fde68a;background:#fffbeb}.recommendation.strong{border-color:#bbf7d0;background:#f0fdf4}.assessment{margin:11px 0;border:1px solid #dbe4ea;border-radius:7px;overflow:hidden;break-inside:avoid}.assessment header{display:flex;justify-content:space-between;gap:9px;padding:7px 8px;background:#f8fafc}.assessment h3{margin:0;font-size:11px}.assessment h3 span,.assessment p{color:#64748b}.assessment p{margin:2px 0 0;font-size:8px}.result{text-align:right}.result>b{display:block;font-size:13px}.result>span{display:block;color:#0f766e;font-weight:700}.diagnosis{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:5px;padding:7px 8px;background:#fbfdff;border-top:1px solid #e2e8f0}.diagnosis>div{border:1px solid #dbeafe;border-radius:4px;padding:5px}.diagnosis b{font-size:8px;color:#0f766e}.diagnosis p,.notice{margin:2px 0;font-size:8px;color:#475569}.notice{padding:7px 8px;background:#fff7ed}.footer{margin-top:16px;padding-top:7px;border-top:1px solid #e2e8f0;color:#94a3b8;font-size:8px;display:flex;justify-content:space-between}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{padding:14mm 13mm 16mm}}</style></head><body><main class="page"><header class="hero"><div><h1>學生跨學年個人表現報告</h1><p><b>${escapeHtml(report.student.name)}</b> · 學生編號：${escapeHtml(report.student.studentNumber)}</p><p>本報告只包含本人的成績及課題分析，不顯示其他學生資料。</p></div><div class="scope">${escapeHtml(scope)}<br><small>生成日期：${escapeHtml(new Date().toLocaleDateString("zh-HK"))}</small></div></header><div class="stats"><div class="stat"><span>已評分項</span><b>${scored.length}</b></div><div class="stat"><span>跨年平均</span><b>${average === null ? "—" : `${average}%`}</b></div><div class="stat"><span>涉及學年</span><b>${years.length}</b></div><div class="stat"><span>強項單元</span><b>${strengths.length}</b></div></div><section class="section"><h2 class="title">跨學年表現判讀</h2><div class="insights"><div class="insight"><b>成績趨勢</b><p>${trend === null ? "需最少兩項已評分紀錄才可判讀趨勢。" : `由首項至最近一項${trend >= 0 ? "上升" : "下降"} ${Math.abs(trend)} 個百分點。`}</p></div><div class="insight"><b>學年覆蓋</b><p>已納入 ${years.length} 個學年、${scored.length} 項已評分紀錄及 ${units.length} 個課題單元。</p></div><div class="insight"><b>分析原則</b><p>只以已完成且已標記課題的作答生成強弱項；遲交、欠交、缺席不納入課題分析。</p></div></div><table style="margin-top:7px"><thead><tr><th>學年</th><th class="right">個人平均</th></tr></thead><tbody>${yearsRows}</tbody></table></section>${radar ? `<section class="section"><h2 class="title">課題掌握雷達圖</h2>${radar}</section>` : ""}<section class="section"><h2 class="title">課題強弱與個人學習建議</h2><table><thead><tr><th>課題／學習單元</th><th class="center">得分</th><th class="center">掌握度</th><th class="center">判讀</th></tr></thead><tbody>${topicRows}</tbody></table>${recommendationRows ? `<div class="recommendations">${recommendationRows}</div>` : ""}</section><section class="section"><h2 class="title">每項測驗、功課及考試的逐題分析</h2>${assessmentRows}</section><footer class="footer"><span>${escapeHtml(report.student.studentNumber)} · ${escapeHtml(scope)}</span><span>學生個人成績報告</span></footer></main></body></html>`;
  const win = window.open("", "_blank");
  if (!win) throw new Error("無法開啟報告視窗，請允許彈出視窗。");
  win.document.write(html);
  win.document.close();
  window.setTimeout(() => win.print(), 350);
}

export default function StudentPortal() {
  const { user, logout } = useAuth();
  const utils = trpc.useUtils();
  const { data: report, isLoading, error } = trpc.studentProfile.mine.useQuery();
  const [selectedSubjectId, setSelectedSubjectId] = useState("all");
  const [language, setLanguage] = useState<StudentLanguage>("zh");
  const copy = language === "en" ? {
    portalTitle: "Student Performance Report", loggedIn: "Signed in", logout: "Sign out", reportTitle: "Complete cross-year personal performance analysis",
    reportIntro: "Review your cross-year trends, topic mastery, strengths, and priority next steps. Analysis uses your own achievement data and privacy-protected class benchmarks only.",
    allSubjects: "All subjects (cross-year)", pdf: "Full PDF report", subject: "Subject", assessmentAnalysis: "Complete item-by-item assessment analysis",
    assessmentIntro: "Each quiz, test, assignment, and examination includes your marks, tagged topics, overall rank, and anonymous item-level class averages where the privacy threshold is met.",
    noAssessments: "No assessment records are available in this scope.",
  } : {
    portalTitle: "學生個人成績報告", loggedIn: "已登入", logout: "登出", reportTitle: "跨學年完整個人表現分析",
    reportIntro: "查看自己的跨學年成績趨勢、課題掌握、強項及優先改善項目。分析只使用本人的成績資料及符合私隱門檻的班級基準。",
    allSubjects: "所有科目（跨學年）", pdf: "完整 PDF 報告", subject: "科目", assessmentAnalysis: "每項評估的完整逐題分析",
    assessmentIntro: "每一項測驗、小測、功課及考試均展示個人得分、所屬課題、整份評估名次，以及符合私隱門檻時的匿名逐題班均。",
    noAssessments: "此範圍暫無評估紀錄。",
  };
  const selectedAssessments = useMemo(() => (report?.assessments ?? []).filter(item => selectedSubjectId === "all" || item.subjectId === selectedSubjectId), [report, selectedSubjectId]);
  const selectedTopics = useMemo(() => (report?.topics ?? []).filter(topic => selectedSubjectId === "all" || topic.id.startsWith(`${selectedSubjectId}::`)), [report, selectedSubjectId]);
  const scored = useMemo(() => selectedAssessments.filter(item => item.pct !== null), [selectedAssessments]);
  const units = useMemo(() => report ? buildTopicUnits(selectedTopics, report.subjects, selectedSubjectId) : [], [report, selectedTopics, selectedSubjectId]);
  const years = useMemo(() => yearSummary(selectedAssessments), [selectedAssessments]);
  const subjectYear = useMemo(() => subjectYearSummary(selectedAssessments), [selectedAssessments]);
  const average = scored.length ? Math.round(scored.reduce((sum, item) => sum + (item.pct ?? 0), 0) / scored.length) : null;
  const strengths = useMemo(() => units.filter(unit => unit.status === "strong").sort((a, b) => b.pct - a.pct).slice(0, 3), [units]);
  const priority = useMemo(() => units.filter(unit => unit.status === "priority").slice(0, 3), [units]);
  const developing = useMemo(() => units.filter(unit => unit.status === "developing").slice(0, 2), [units]);
  const recommendations = useMemo(() => getRecommendations(priority, developing, strengths, language), [priority, developing, strengths, language]);
  const trend = scored.length >= 2 ? (scored[scored.length - 1].pct ?? 0) - (scored[0].pct ?? 0) : null;
  const recentAverage = years.length ? years[years.length - 1].pct : null;
  const previousAverage = years.length > 1 ? years[years.length - 2].pct : null;
  const comparison = useMemo(() => classComparisonSummary(selectedAssessments), [selectedAssessments]);
  const { data: topicProgress } = trpc.studentProfile.topicProgress.useQuery();
  const progressByTopic = useMemo(() => new Map((topicProgress ?? []).map(item => [item.topicKey, item.status as StudentRevisionStatus])), [topicProgress]);
  const revisionCounts = useMemo(() => ({
    completed: selectedTopics.filter(topic => progressByTopic.get(topic.id) === "completed").length,
    review: selectedTopics.filter(topic => progressByTopic.get(topic.id) === "review").length,
  }), [progressByTopic, selectedTopics]);
  const setTopicProgress = trpc.studentProfile.setTopicProgress.useMutation({
    onSuccess: () => utils.studentProfile.topicProgress.invalidate(),
    onError: mutationError => toast.error(mutationError.message),
  });
  const updateTopicProgress = (topicKey: string, status: StudentRevisionStatus | null) => setTopicProgress.mutate({ topicKey, status });

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-slate-50 text-slate-600"><Loader2 className="h-5 w-5 animate-spin" /><span className="ml-2 text-sm">正在安全載入你的完整個人報告…</span></div>;
  if (error) return <PortalError title="未能載入個人成績" detail={error.message} logout={logout} />;
  if (!report) return <PortalError title="尚未找到你的成績記錄" detail="此登入帳戶已設為學生帳戶，但未能在現有名單中以學生編號配對。請通知老師核對學生編號。" logout={logout} warning />;

  return <main className="h-[100dvh] min-h-0 overflow-y-auto overscroll-contain bg-slate-50 [scrollbar-gutter:stable]" style={{ WebkitOverflowScrolling: "touch" }}><header className="sticky top-0 z-20 border-b border-teal-900 bg-slate-950 text-white shadow-sm"><div className="mx-auto flex max-w-7xl flex-col gap-4 px-4 py-4 sm:flex-row sm:items-center sm:justify-between md:px-6"><div className="flex items-center gap-3"><div className="rounded-lg bg-teal-500/20 p-2"><UserRoundCheck className="h-5 w-5 text-teal-300" /></div><div><p className="text-sm font-bold">{copy.portalTitle}</p><p className="text-xs text-slate-300">{report.student.name} · {report.student.studentNumber}</p></div></div><div className="flex flex-wrap items-center gap-2"><div className="flex rounded-md border border-slate-600 p-0.5 text-xs"><button type="button" aria-pressed={language === "zh"} onClick={() => setLanguage("zh")} className={`rounded px-2 py-1 ${language === "zh" ? "bg-teal-600 text-white" : "text-slate-300 hover:bg-slate-800"}`}>中文</button><button type="button" aria-pressed={language === "en"} onClick={() => setLanguage("en")} className={`rounded px-2 py-1 ${language === "en" ? "bg-teal-600 text-white" : "text-slate-300 hover:bg-slate-800"}`}>EN</button></div><span className="hidden text-xs text-slate-400 sm:inline">{copy.loggedIn}: {user?.username}</span><Button size="sm" variant="outline" className="border-slate-600 bg-transparent text-white hover:bg-slate-800 hover:text-white" onClick={() => logout()}><LogOut className="h-4 w-4" />{copy.logout}</Button></div></div></header><div className="mx-auto max-w-7xl space-y-5 p-4 pb-10 md:p-6 md:pb-12">
    <section className="rounded-xl border border-teal-200 bg-white p-5 shadow-sm"><div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex items-center gap-2"><ShieldCheck className="h-5 w-5 text-teal-700" /><h1 className="text-xl font-bold text-slate-900">{copy.reportTitle}</h1></div><p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-600">{copy.reportIntro}</p>{report.student.observedNames.length > 1 && <p className="mt-2 text-xs text-slate-500">歷史名單名稱：{report.student.observedNames.join("、")}</p>}</div><div className="flex flex-col gap-2 sm:flex-row"><select value={selectedSubjectId} onChange={event => setSelectedSubjectId(event.target.value)} className="h-10 min-w-56 rounded-md border border-slate-300 bg-white px-3 text-sm"><option value="all">{copy.allSubjects}</option>{report.subjects.map(subject => <option key={subject.subjectId} value={subject.subjectId}>{subject.subjectCode} · {subject.subjectName}</option>)}</select><Button className="bg-teal-700 hover:bg-teal-800" onClick={() => { try { printStudentReport(report, selectedSubjectId); } catch (printError) { toast.error(printError instanceof Error ? printError.message : "無法產生 PDF 報告"); } }}><FileDown className="h-4 w-4" />{copy.pdf}</Button></div></div></section>

    <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7"><MetricCard label={language === "en" ? "Cross-year average" : "跨年平均"} value={average === null ? "—" : `${average}%`} tone={scoreTone(average)} /><MetricCard label={language === "en" ? "Graded assessments" : "已評分項"} value={String(scored.length)} tone="text-blue-700" /><MetricCard label={language === "en" ? "School years" : "涉及學年"} value={String(years.length)} tone="text-violet-700" /><MetricCard label={language === "en" ? "Extendable strengths" : "可延伸強項"} value={String(strengths.length)} tone="text-emerald-700" /><MetricCard label={language === "en" ? "Priority review" : "優先改善"} value={String(priority.length)} tone="text-red-700" /><MetricCard label={language === "en" ? "Revision complete" : "已完成重溫"} value={String(revisionCounts.completed)} tone="text-teal-700" /><MetricCard label={language === "en" ? "To review" : "需重溫"} value={String(revisionCounts.review)} tone="text-amber-700" /></section>

    <section className="overflow-hidden rounded-xl border border-indigo-100 bg-white shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3 border-b border-indigo-100 bg-indigo-50/60 px-5 py-4"><div><div className="flex items-center gap-2"><UsersRound className="h-5 w-5 text-indigo-700" /><h2 className="font-bold text-slate-900">{language === "en" ? "My gap against anonymous class benchmarks" : "與本班整體的差距"}</h2></div><p className="mt-1 text-xs leading-relaxed text-slate-500">{language === "en" ? "Only your own marks and anonymous class averages are shown. No classmates’ names, individual marks, ranks, or score distribution are shown." : "只顯示本人的成績與匿名班級平均；不會顯示同學姓名、個別分數、名次或分數分布。"}</p></div>{comparison && <span className={`rounded-full px-3 py-1 text-xs font-bold ${comparison.gap >= 0 ? "bg-emerald-100 text-emerald-700" : "bg-amber-100 text-amber-700"}`}>{language === "en" ? `${comparison.gap >= 0 ? "Above" : "Below"} class average by ${Math.abs(comparison.gap)} pp` : `${comparison.gap >= 0 ? "高於" : "低於"}班均 ${Math.abs(comparison.gap)} 個百分點`}</span>}</div>{comparison ? <div className="grid gap-4 p-4 lg:grid-cols-[minmax(0,1.3fr)_minmax(280px,.7fr)]"><div className="min-h-[230px] rounded-lg border border-indigo-100 bg-indigo-50/20 p-3"><ResponsiveContainer width="100%" height={210}><BarChart data={comparison.rows} margin={{ top: 10, right: 12, left: -20, bottom: 2 }}><CartesianGrid strokeDasharray="3 3" stroke="#e0e7ff" /><XAxis dataKey="label" tick={{ fontSize: 9 }} interval="preserveStartEnd" /><YAxis domain={[0, 100]} tick={{ fontSize: 10 }} unit="%" /><Tooltip labelFormatter={(_label, payload) => payload?.[0]?.payload?.fullLabel || ""} /><Bar dataKey="personalPct" name="我的成績" fill="#0f766e" radius={[4, 4, 0, 0]} /><Bar dataKey="classAverage" name="班級平均" fill="#818cf8" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer></div><div className="grid content-center gap-3 sm:grid-cols-3 lg:grid-cols-1"><ComparisonMetric label={language === "en" ? "My average" : "我的平均"} value={`${comparison.personalAverage}%`} tone={scoreTone(comparison.personalAverage)} /><ComparisonMetric label={language === "en" ? "Class average" : "班級平均"} value={`${comparison.classAverage}%`} tone="text-indigo-700" /><ComparisonMetric label={language === "en" ? "Average gap" : "平均差距"} value={`${comparison.gap >= 0 ? "+" : ""}${comparison.gap} pp`} tone={comparison.gap >= 0 ? "text-emerald-700" : "text-amber-700"} /></div></div> : <div className="flex items-start gap-3 p-5 text-sm leading-relaxed text-slate-500"><Info className="mt-0.5 h-5 w-5 shrink-0 text-indigo-600" /><p>目前未能安全顯示班級比較。系統只會在同一評估中至少有 <b>3 名其他同學</b> 已正常完成評分時，才顯示匿名班級平均；缺席、欠交、遲交及未完成輸入均不會納入。</p></div>}</section>

    <section className="overflow-hidden rounded-xl border border-blue-100 bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-blue-100 bg-blue-50/70 px-5 py-4"><div><div className="flex items-center gap-2"><LineChartIcon className="h-5 w-5 text-blue-700" /><h2 className="font-bold text-slate-900">{language === "en" ? "Cross-year trend and interpretation" : "跨學年表現趨勢與判讀"}</h2></div><p className="mt-1 text-xs text-slate-500">{language === "en" ? "Completed assessments are combined by school year and selected subject to show your long-term change." : "所有已完成評估均會按年份及所選科目整合，讓你看見長期變化。"}</p></div><span className="rounded-full bg-white px-3 py-1 text-xs font-semibold text-blue-700 shadow-sm">{selectedSubjectId === "all" ? "所有科目" : report.subjects.find(subject => subject.subjectId === selectedSubjectId)?.subjectCode}</span></div><div className="grid gap-3 p-4 lg:grid-cols-[minmax(0,1.45fr)_minmax(270px,1fr)]"><div className="min-h-[235px] rounded-lg border border-blue-100 bg-blue-50/30 p-3">{subjectYear.length >= 3 ? <ResponsiveContainer width="100%" height={215}><RadarChart data={subjectYear}><PolarGrid stroke="#dbeafe" /><PolarAngleAxis dataKey="shortLabel" tick={{ fontSize: 10 }} /><PolarRadiusAxis domain={[0, 100]} tick={{ fontSize: 9 }} /><Radar dataKey="pct" name="個人平均" stroke="#2563eb" fill="#2563eb" fillOpacity={0.2} /><Tooltip formatter={(value: number) => [`${value}%`, "個人平均"]} /></RadarChart></ResponsiveContainer> : scored.length ? <ResponsiveContainer width="100%" height={215}><LineChart data={scored.map(item => ({ label: `${item.yearLabel} · ${item.code || item.title}`, fullLabel: `${item.yearLabel} · ${item.subjectCode} · ${item.title}`, pct: item.pct }))} margin={{ top: 12, right: 16, left: -18, bottom: 8 }}><CartesianGrid strokeDasharray="3 3" stroke="#dbeafe" /><XAxis dataKey="label" tick={{ fontSize: 9 }} interval="preserveStartEnd" /><YAxis domain={[0, 100]} tick={{ fontSize: 10 }} unit="%" /><Tooltip formatter={(value: number) => [`${value}%`, "個人成績"]} labelFormatter={(_label, payload) => payload?.[0]?.payload?.fullLabel || ""} /><Line type="monotone" dataKey="pct" stroke="#0f766e" strokeWidth={3} dot={{ r: 4, fill: "#0f766e" }} /></LineChart></ResponsiveContainer> : <EmptyHint text="尚未有可繪製的已完成個人成績。" />}</div><div className="space-y-2"><InsightCard icon={<Target className="h-4 w-4 text-blue-700" />} title="跨年趨勢判讀" body={trend === null ? "需要最少兩項已評分紀錄才可判讀趨勢。" : `由首項至最近一項成績${trend >= 0 ? "上升" : "下降"} ${Math.abs(trend)} 個百分點。`} /><InsightCard icon={<BrainCircuit className="h-4 w-4 text-violet-700" />} title="學年變化" body={recentAverage === null ? "目前沒有已評分學年資料。" : previousAverage === null ? `最近學年平均為 ${recentAverage}%。` : `最近學年平均 ${recentAverage}%，較上一個有成績的學年${recentAverage >= previousAverage ? "上升" : "下降"} ${Math.abs(recentAverage - previousAverage)} 個百分點。`} /><InsightCard icon={<ShieldCheck className="h-4 w-4 text-emerald-700" />} title="分析證據" body={`已使用 ${scored.length} 項已評分紀錄、${units.length} 個學習單元及 ${selectedTopics.length} 個已標記課題。`} /></div></div>{years.length > 0 && <div className="border-t border-slate-100 px-4 py-3"><p className="mb-2 text-xs font-bold text-slate-600">學年摘要</p><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4">{years.map(year => <div key={year.yearLabel} className="rounded-lg border border-slate-200 bg-white px-3 py-2"><p className="text-xs font-semibold text-slate-700">{year.yearLabel}</p><p className="mt-0.5 text-[11px] text-slate-500">{year.subjects} · {year.count} 項評估</p><p className={`mt-1 font-mono text-lg font-bold ${scoreTone(year.pct)}`}>{year.pct}%</p></div>)}</div></div>}</section>

    <section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 bg-slate-50 px-5 py-4"><div><div className="flex items-center gap-2"><RadarIcon className="h-5 w-5 text-teal-700" /><h2 className="font-bold text-slate-900">{language === "en" ? "Topic mastery, strengths, and priorities" : "課題掌握、強項與改善重點"}</h2></div><p className="mt-1 text-xs text-slate-500">{language === "en" ? "Strengths and priorities combine only completed, topic-tagged question marks. Late, missing, absent, and incomplete entries are excluded from topic analysis." : "強弱項由已完成且有課題標記的逐題成績自動整合；遲交、欠交、缺席及未完成輸入不納入課題分析。"}</p></div><div className="text-xs text-slate-500"><b className="text-red-600">{priority.length}</b> 優先 · <b className="text-amber-600">{developing.length}</b> 需鞏固 · <b className="text-emerald-600">{strengths.length}</b> 強項</div></div>{units.length ? <><div className="grid gap-3 p-4 lg:grid-cols-[minmax(0,1.15fr)_minmax(280px,.85fr)]"><div className="min-h-[265px] rounded-lg border border-teal-100 bg-teal-50/20 p-2">{units.length >= 3 ? <ResponsiveContainer width="100%" height={245}><RadarChart data={[...units].sort((a, b) => b.max - a.max).slice(0, 6)}><PolarGrid stroke="#ccfbf1" /><PolarAngleAxis dataKey="learningUnit" tick={{ fontSize: 9 }} /><PolarRadiusAxis domain={[0, 100]} tick={{ fontSize: 8 }} /><Radar dataKey="pct" name="掌握度" stroke="#0f766e" fill="#0f766e" fillOpacity={0.22} /><Tooltip formatter={(value: number) => [`${value}%`, "掌握度"]} /></RadarChart></ResponsiveContainer> : <ResponsiveContainer width="100%" height={245}><BarChart data={units}><CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" /><XAxis dataKey="learningUnit" tick={{ fontSize: 9 }} interval={0} /><YAxis domain={[0, 100]} tick={{ fontSize: 9 }} /><Tooltip formatter={(value: number) => [`${value}%`, "掌握度"]} /><Bar dataKey="pct" radius={[4, 4, 0, 0]}>{units.map(unit => <Cell key={unit.id} fill={colorForPct(unit.pct)} />)}</Bar></BarChart></ResponsiveContainer>}</div><div className="grid gap-3"><TopicList title={language === "en" ? "Extendable strengths" : "可延伸的強項"} empty={language === "en" ? "No tagged topic has yet reached 70% or above." : "尚未有達 70% 或以上的已標記課題。"} units={strengths} status="strong" /><TopicList title={language === "en" ? "Priority and developing topics" : "優先鞏固與需加強課題"} empty={language === "en" ? "No tagged topic is currently below 70%." : "目前未見低於 70% 的已標記課題。"} units={[...priority, ...developing]} status="priority" /></div></div><div className="border-t border-slate-100 bg-slate-50/50 p-4"><div className="flex items-center gap-2"><Lightbulb className="h-4 w-4 text-amber-600" /><h3 className="text-sm font-bold text-slate-800">{language === "en" ? "Personal learning recommendations" : "個人學習建議摘要"}</h3></div>{recommendations.length ? <div className="mt-3 grid gap-2 lg:grid-cols-3">{recommendations.map((recommendation, index) => <div key={`${recommendation.topic.id}-${index}`} className={`rounded-lg border p-3 ${recommendation.tone === "priority" ? "border-red-200 bg-red-50/60" : recommendation.tone === "developing" ? "border-amber-200 bg-amber-50/60" : "border-emerald-200 bg-emerald-50/60"}`}><p className={`text-xs font-bold ${recommendation.tone === "priority" ? "text-red-800" : recommendation.tone === "developing" ? "text-amber-800" : "text-emerald-800"}`}>{recommendation.title}</p><p className="mt-1 text-[11px] leading-relaxed text-slate-600">{recommendation.body}</p><p className="mt-2 text-[10px] text-slate-500">{recommendation.topic.label} · {recommendation.topic.earned}/{recommendation.topic.max} · {recommendation.topic.pct}% · {recommendation.topic.assessmentCount} 項評估</p></div>)}</div> : <p className="mt-2 text-sm text-slate-400">需累積更多已完成並已標記課題的成績，才可產生個人化建議。</p>}</div><div className="overflow-x-auto border-t border-slate-100"><table className="w-full min-w-[800px] text-sm"><thead className="bg-slate-50 text-left text-xs font-semibold text-slate-500"><tr><th className="px-5 py-3">程度／學習單元</th><th className="px-4 py-3">學習目標</th><th className="px-4 py-3 text-center">證據</th><th className="px-4 py-3 text-right">掌握度</th><th className="px-5 py-3 text-center">判讀</th></tr></thead><tbody className="divide-y divide-slate-100">{units.map(unit => <tr key={unit.id}><td className="px-5 py-3"><p className="font-semibold text-slate-800">{unit.label}</p><p className="text-xs text-slate-500">{unit.level}</p></td><td className="px-4 py-3 text-xs text-slate-600">{unit.objectives.map(topic => topic.objective).join("；")}</td><td className="px-4 py-3 text-center text-xs font-mono text-slate-600">{unit.itemCount} 題 · {unit.assessmentCount} 項</td><td className="px-4 py-3"><div className="ml-auto w-28"><div className="mb-1 flex justify-between text-xs"><span className="font-mono text-slate-600">{unit.earned}/{unit.max}</span><b className={scoreTone(unit.pct)}>{unit.pct}%</b></div><div className="h-1.5 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${scoreBackground(unit.pct)}`} style={{ width: `${unit.pct}%` }} /></div></div></td><td className="px-5 py-3 text-center"><span className={`rounded-full px-2 py-1 text-xs font-semibold ${topicStatusClass(unit.status)}`}>{topicStatusLabel(unit.status, language)}</span></td></tr>)}</tbody></table></div></> : <EmptyHint text="尚未有已完成並已標記課題的個人成績。請等待老師完成評分及課題標記。" />}</section>

    <StudyTracker topics={selectedTopics} progressByTopic={progressByTopic} pending={setTopicProgress.isPending} onSet={updateTopicProgress} language={language} />

    <section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div className="border-b border-slate-200 bg-slate-50 px-5 py-4"><div className="flex items-center gap-2"><BookOpenCheck className="h-5 w-5 text-blue-700" /><h2 className="font-bold text-slate-900">{copy.assessmentAnalysis}</h2></div><p className="mt-1 text-xs text-slate-500">{copy.assessmentIntro}</p></div><div className="divide-y divide-slate-100">{selectedAssessments.length ? selectedAssessments.map(assessment => <AssessmentDetail key={assessment.id} assessment={assessment} language={language} />) : <EmptyHint text={copy.noAssessments} />}</div></section>
  </div></main>;
}

function StudyTracker({ topics, progressByTopic, pending, onSet, language }: { topics: PortalTopic[]; progressByTopic: Map<string, StudentRevisionStatus>; pending: boolean; onSet: (topicKey: string, status: StudentRevisionStatus | null) => void; language: StudentLanguage }) {
  const english = language === "en";
  const ordered = [...topics].sort((a, b) => {
    const rank = (status: StudentRevisionStatus | undefined) => status === "review" ? 0 : status === "completed" ? 2 : 1;
    return rank(progressByTopic.get(a.id)) - rank(progressByTopic.get(b.id)) || a.learningUnit.localeCompare(b.learningUnit) || a.objective.localeCompare(b.objective);
  });
  return <section className="overflow-hidden rounded-xl border border-amber-200 bg-white shadow-sm"><div className="flex flex-col gap-3 border-b border-amber-100 bg-amber-50/70 px-5 py-4 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex items-center gap-2"><BookOpenCheck className="h-5 w-5 text-amber-700" /><h2 className="font-bold text-slate-900">{english ? "My topic revision list" : "我的課題重溫清單"}</h2></div><p className="mt-1 text-xs leading-relaxed text-slate-600">{english ? "Mark a topic in your report as completed or to review. This list belongs to your account only and never changes teacher marks, topic analysis, or class statistics." : "把自己報告中的課題標為「已完成重溫」或「需重溫」。此清單只屬於你的帳戶，不會更改老師評分、課題分析或班級統計。"}</p></div><span className="shrink-0 rounded-full bg-white px-3 py-1 text-xs font-semibold text-amber-800 shadow-sm">{ordered.length} {english ? "trackable topics" : "項可追蹤課題"}</span></div>{ordered.length ? <div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{ordered.map(topic => {
    const current = progressByTopic.get(topic.id);
    return <article key={topic.id} className={`min-w-0 rounded-lg border p-3 ${current === "completed" ? "border-emerald-200 bg-emerald-50/40" : current === "review" ? "border-amber-200 bg-amber-50/50" : "border-slate-200 bg-white"}`}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="text-[11px] font-bold text-slate-500">{topic.level} · {topic.learningUnit}</p><p className="mt-1 break-words text-sm font-semibold leading-snug text-slate-800">{topic.objective}</p><p className={`mt-1 font-mono text-xs font-bold ${scoreTone(topic.pct)}`}>{topic.earned}/{topic.max} · {topic.pct}%</p></div>{current === "completed" ? <CheckCircle2 className="h-5 w-5 shrink-0 text-emerald-600" /> : current === "review" ? <RotateCcw className="h-5 w-5 shrink-0 text-amber-600" /> : <Circle className="h-5 w-5 shrink-0 text-slate-300" />}</div><div className="mt-3 grid grid-cols-2 gap-2"><Button type="button" size="sm" variant={current === "completed" ? "default" : "outline"} className={current === "completed" ? "bg-emerald-600 hover:bg-emerald-700" : "border-emerald-200 text-emerald-700 hover:bg-emerald-50"} disabled={pending} onClick={() => onSet(topic.id, current === "completed" ? null : "completed")}><CheckCircle2 className="h-3.5 w-3.5" />{english ? "Completed" : "已完成"}</Button><Button type="button" size="sm" variant={current === "review" ? "default" : "outline"} className={current === "review" ? "bg-amber-600 hover:bg-amber-700" : "border-amber-200 text-amber-700 hover:bg-amber-50"} disabled={pending} onClick={() => onSet(topic.id, current === "review" ? null : "review")}><RotateCcw className="h-3.5 w-3.5" />{english ? "Review" : "需重溫"}</Button></div></article>;
  })}</div> : <EmptyHint text={english ? "There are no tagged topics in this subject scope to add to your revision list yet." : "在已選科目中暫未有已標記的課題可加入重溫清單。"} />}</section>;
}

function ComparisonMetric({ label, value, tone }: { label: string; value: string; tone: string }) { return <div className="rounded-lg border border-indigo-100 bg-white p-3"><p className="text-xs font-semibold text-slate-500">{label}</p><p className={`mt-1 font-mono text-xl font-bold ${tone}`}>{value}</p></div>; }
function MetricCard({ label, value, tone }: { label: string; value: string; tone: string }) { return <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">{label}</p><p className={`mt-1 font-mono text-2xl font-bold ${tone}`}>{value}</p></div>; }
function InsightCard({ icon, title, body }: { icon: React.ReactNode; title: string; body: string }) { return <div className="rounded-lg border border-slate-200 bg-white p-3"><div className="flex items-center gap-2"><span className="rounded bg-slate-50 p-1.5">{icon}</span><p className="text-xs font-bold text-slate-800">{title}</p></div><p className="mt-2 text-[11px] leading-relaxed text-slate-600">{body}</p></div>; }
function EmptyHint({ text }: { text: string }) { return <div className="flex min-h-36 items-center justify-center p-8 text-center text-sm text-slate-400">{text}</div>; }
function TopicList({ title, empty, units, status }: { title: string; empty: string; units: TopicUnit[]; status: TopicStatus }) { const panel = status === "strong" ? "border-emerald-200 bg-emerald-50/50" : "border-red-200 bg-red-50/40"; const heading = status === "strong" ? "text-emerald-800" : "text-red-800"; return <div className={`rounded-lg border p-3 ${panel}`}><p className={`mb-2 text-xs font-bold ${heading}`}>{title}</p>{units.length ? <div className="space-y-2">{units.map(unit => <div key={unit.id} className="flex items-center justify-between gap-3 border-b border-white/70 pb-2 last:border-0 last:pb-0"><div className="min-w-0"><p className="truncate text-xs font-semibold text-slate-800">{unit.label}</p><p className="text-[10px] text-slate-500">{unit.assessmentCount} 項評估／{unit.itemCount} 題</p></div><div className="shrink-0 text-right"><p className={`font-mono text-sm font-bold ${scoreTone(unit.pct)}`}>{unit.pct}%</p><p className="text-[10px] font-mono text-slate-500">{unit.earned}/{unit.max}</p></div></div>)}</div> : <p className="text-xs text-slate-400">{empty}</p>}</div>; }
function AssessmentDetail({ assessment, language }: { assessment: PortalAssessment; language: StudentLanguage }) {
  const english = language === "en";
  const answered = assessment.questions.filter(question => question.pct !== null);
  const low = [...answered].sort((a, b) => (a.pct ?? 101) - (b.pct ?? 101)).slice(0, 3);
  const high = [...answered].sort((a, b) => (b.pct ?? -1) - (a.pct ?? -1)).slice(0, 2);
  const canDiagnose = assessment.status === "complete" || assessment.status === "late";
  const comparison = assessment.classBenchmark;
  const resultLabel = assessment.pct === null ? (english ? "Not scored" : "未計分") : `${assessment.pct}%`;
  const privacyNote = english
    ? "Question-level comparison shows anonymous class averages only when at least 3 other classmates completed this assessment. No names, individual marks, or score distribution are shown."
    : "逐題比較只會在至少 3 名其他同學完成同一評估時顯示匿名班級平均；不會顯示同學姓名、個別分數或分數分布。";
  return <details className="group">
    <summary className="cursor-pointer list-none px-5 py-4 hover:bg-slate-50"><div className="flex flex-wrap items-center justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><ChevronRight className="h-4 w-4 text-slate-400 transition-transform group-open:rotate-90" /><span className="font-semibold text-slate-900">{assessment.title}{assessment.code && <span className="ml-1 font-mono text-sm text-slate-500">({assessment.code})</span>}</span><span className={`rounded border px-2 py-0.5 text-xs font-semibold ${statusStyle(assessment.status)}`}>{statusLabel(assessment.status, language)}</span></div><p className="mt-1 text-xs text-slate-500">{assessment.yearLabel} · {assessment.subjectCode} · {assessment.className} · {assessment.nature}{assessment.date ? ` · ${assessment.date}` : ""}</p></div><div className="text-right"><p className="font-mono text-lg font-bold text-slate-800">{assessment.total === null ? "—" : `${assessment.total}/${assessment.max}`}</p><p className={`text-xs font-semibold ${scoreTone(assessment.pct)}`}>{resultLabel}</p></div></div></summary>
    <div className="border-t border-slate-100 bg-slate-50/60 p-4">
      {canDiagnose ? <div className="mb-3 grid gap-2 lg:grid-cols-4"><div className="rounded-lg border border-blue-100 bg-blue-50/40 p-3"><p className="text-xs font-bold text-blue-800">{english ? "Personal diagnosis" : "個人診斷摘要"}</p><p className="mt-1 text-[11px] leading-relaxed text-slate-600">{english ? `Completed ${answered.length}/${assessment.questions.length} items; your result is ${assessment.pct}%${low[0]?.topic ? `; review “${low[0].topic.learningUnit}” first.` : "."}` : `已完成 ${answered.length}/${assessment.questions.length} 題；本次個人成績為 ${assessment.pct}%${low[0]?.topic ? `，建議先重溫「${low[0].topic.learningUnit}」` : "。"}`}</p></div><div className="rounded-lg border border-indigo-100 bg-indigo-50/40 p-3"><p className="text-xs font-bold text-indigo-800">{english ? "Anonymous class comparison" : "匿名班級比較"}</p>{comparison ? <p className="mt-1 text-[11px] leading-relaxed text-slate-600">{english ? <>Class average <b>{comparison.averagePct}%</b>; you are <b className={assessment.pct !== null && assessment.pct >= comparison.averagePct ? "text-emerald-700" : "text-amber-700"}>{assessment.pct !== null && assessment.pct >= comparison.averagePct ? "+" : ""}{(assessment.pct ?? 0) - comparison.averagePct} pp</b>; position <b>{comparison.rank ? `${comparison.rank}/${comparison.rankedCount}` : "—"}</b>.</> : <>班級平均 <b>{comparison.averagePct}%</b>；你與班均相差 <b className={assessment.pct !== null && assessment.pct >= comparison.averagePct ? "text-emerald-700" : "text-amber-700"}>{assessment.pct !== null && assessment.pct >= comparison.averagePct ? "+" : ""}{(assessment.pct ?? 0) - comparison.averagePct} 個百分點</b>；你的名次為 <b>{comparison.rank ? `${comparison.rank}/${comparison.rankedCount}` : "—"}</b>。</>}</p> : <p className="mt-1 text-[11px] leading-relaxed text-slate-500">{english ? "Not available yet: fewer than 3 other completed peer records, or this entry is not a normal completed result." : "暫未能顯示：少於 3 名其他同學完成評分，或此項不是正常完成的個人成績。"}</p>}</div><QuestionFocus title={english ? "Priority follow-up" : "優先跟進"} tone="red" questions={low} empty={english ? "No question-level evidence available." : "暫無可判讀題目。"} /><QuestionFocus title={english ? "Extend a strength" : "可延伸強項"} tone="green" questions={high} empty={english ? "No question-level evidence available." : "暫無可判讀題目。"} /></div> : <div className="mb-3 rounded-lg border border-orange-200 bg-orange-50 p-3 text-xs leading-relaxed text-orange-800">{assessment.status === "absent" ? (english ? "This assessment is marked absent. It is shown as 0 for your personal score but is not included in topic-strength analysis." : "此項標示為缺席，個人成績以 0 分顯示，但不納入課題強弱分析。") : assessment.status === "missing" ? (english ? "This assignment is marked missing. It is shown as 0 for your personal score but is not included in topic-strength analysis." : "此作業標示為欠交，個人成績以 0 分顯示，但不納入課題強弱分析。") : (english ? "This assessment is not fully entered, so item-level analysis is not yet available." : "此項尚未完成輸入，因此暫未能生成逐題診斷。")}</div>}
      <div className="mb-3 flex items-start gap-2 rounded-lg border border-indigo-100 bg-white px-3 py-2 text-[11px] leading-relaxed text-slate-600"><Info className="mt-0.5 h-4 w-4 shrink-0 text-indigo-600" />{privacyNote}</div>
      <div className="overflow-x-auto rounded-lg border border-slate-200 bg-white"><table className="w-full min-w-[890px] text-xs"><thead><tr className="bg-teal-700 text-white"><th className="px-3 py-2 text-left">{english ? "Question" : "題號"}</th><th className="px-3 py-2 text-left">{english ? "Topic (level / unit / objective)" : "所屬課題（程度／單元／目標）"}</th><th className="px-3 py-2 text-right">{english ? "My mark" : "個人得分"}</th><th className="px-3 py-2 text-right">%</th><th className="px-3 py-2 text-right">{english ? "Anon. class avg." : "匿名班均"}</th><th className="px-3 py-2 text-right">{english ? "My gap" : "我的差距"}</th></tr></thead><tbody>{assessment.questions.length ? assessment.questions.map((question, index) => {
        const gap = question.pct !== null && question.classBenchmark ? question.pct - question.classBenchmark.pct : null;
        return <tr key={`${assessment.id}-${question.label}-${index}`} className={index % 2 ? "bg-slate-50" : "bg-white"}><td className="px-3 py-2 font-semibold text-slate-700">{question.label}<span className="font-normal text-slate-400"> / {question.max}</span></td><td className="px-3 py-2">{question.topic ? <><p className="font-medium text-slate-800">{question.topic.level} · {question.topic.learningUnit}</p><p className="mt-0.5 text-slate-500">{question.topic.objective}</p></> : <span className="text-slate-400">{english ? "No topic tagged" : "未標記課題"}</span>}</td><td className="px-3 py-2 text-right font-mono font-bold text-slate-700">{question.score === null ? "—" : `${question.score}/${question.max}`}</td><td className={`px-3 py-2 text-right font-mono font-bold ${scoreTone(question.pct)}`}>{question.pct === null ? "—" : `${question.pct}%`}</td><td className="px-3 py-2 text-right font-mono text-indigo-700">{question.classBenchmark ? <><b>{question.classBenchmark.average}/{question.max}</b><span className="ml-1 text-slate-500">({question.classBenchmark.pct}%)</span></> : "—"}</td><td className={`px-3 py-2 text-right font-mono font-bold ${gap === null ? "text-slate-400" : gap >= 0 ? "text-emerald-700" : "text-amber-700"}`}>{gap === null ? "—" : `${gap >= 0 ? "+" : ""}${gap} pp`}</td></tr>;
      }) : <tr><td colSpan={6} className="px-3 py-6 text-center text-slate-400">{english ? "No mark-sheet items are available." : "未有評分表項目。"}</td></tr>}</tbody></table></div>
    </div>
  </details>;
}
function QuestionFocus({ title, tone, questions, empty }: { title: string; tone: "red" | "green"; questions: PortalQuestion[]; empty: string }) { const styling = tone === "red" ? "border-red-100 bg-red-50/40 text-red-800" : "border-emerald-100 bg-emerald-50/40 text-emerald-800"; return <div className={`rounded-lg border p-3 ${styling}`}><p className="text-xs font-bold">{title}</p>{questions.length ? <div className="mt-1.5 space-y-1">{questions.map((question, index) => <p key={`${question.label}-${index}`} className="text-[11px] text-slate-600"><b className={`font-mono ${tone === "red" ? "text-red-700" : "text-emerald-700"}`}>{question.label}</b> · {question.topic?.learningUnit || "未標記課題"} <span className={`font-mono font-bold ${scoreTone(question.pct)}`}>{question.pct}%</span></p>)}</div> : <p className="mt-1 text-[11px] text-slate-400">{empty}</p>}</div>; }
function PortalError({ title, detail, logout, warning = false }: { title: string; detail: string; logout: () => void; warning?: boolean }) { return <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4"><div className={`max-w-lg rounded-xl border bg-white p-6 text-center ${warning ? "border-amber-200" : "border-red-200"}`}><TriangleAlert className={`mx-auto h-8 w-8 ${warning ? "text-amber-600" : "text-red-600"}`} /><h1 className="mt-3 text-lg font-bold text-slate-900">{title}</h1><p className="mt-2 text-sm leading-relaxed text-slate-600">{detail}</p><Button className="mt-4" variant="outline" onClick={() => logout()}><LogOut className="h-4 w-4" />登出</Button></div></div>; }
